using System.Collections.Generic;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.Abstractions;
using Microsoft.AspNetCore.Mvc.Filters;
using Microsoft.AspNetCore.Routing;
using RaceDay.API.Attributes;
using Xunit;

namespace Race_Day_Part_2.Test
{
    public class SessionAuthorizeTest
    {
        [Fact]
        public async Task OnActionExecuting_MissingSession_ReturnsUnauthorized()
        {
            // Arrange
            var filter = new SessionAuthorizeAttribute("Organiser");
            var httpContext = new DefaultHttpContext(); // No session attached initially
            
            var actionContext = new ActionContext(httpContext, new RouteData(), new ActionDescriptor());
            var context = new ActionExecutingContext(
                actionContext,
                new List<IFilterMetadata>(),
                new Dictionary<string, object>(),
                controller: new object()
            );

            // Act
            await filter.OnActionExecutionAsync(context, () => {
                var actionExecutedContext = new ActionExecutedContext(context, new List<IFilterMetadata>(), controller: new object());
                return Task.FromResult(actionExecutedContext);
            });

            // Assert
            Assert.IsType<UnauthorizedObjectResult>(context.Result);
        }
    }
}
